Monitor solution
Each philosopher is in one of three states: THINKING, HUNGRY, EATING. He may move to EATING only if both neighbours are not
eating. A condition variable self[i] lets a hungry philosopher wait.

 monitor DiningPhilosophers {
 enum { THINKING, HUNGRY, EATING } state[5];
 condition self[5];

 void pickup(int i) {
 state[i] = HUNGRY;
 test(i); /* try to eat */
 if (state[i] != EATING) self[i].wait();
 }
 void putdown(int i) {
 state[i] = THINKING;
 test((i + 4) % 5); /* left neighbour */
 test((i + 1) % 5); /* right neighbour */
 }
 void test(int i) {
 if (state[(i + 4) % 5] != EATING && state[i] == HUNGRY && state[(i + 1) % 5] != EATING) {
 state[i] = EATING;
 self[i].signal();
 }
 }
 initialization_code() { for (int i = 0; i < 5; i++) state[i] = THINKING; }
 }
 /* philosopher i: */ DiningPhilosophers.pickup(i); /* EAT */ DiningPhilosophers.putdown(i);




